// Exige role admin + tenant printag
const user = $input.first().json;
const prev = $('Auth Guard + Parse1').first();
const meta = user.user_metadata || {};
const app  = user.app_metadata  || {};
const role = meta.role || app.role;
const company = meta.company_name;
if (company !== 'printag') throw new Error('FORBIDDEN: tenant inválido');
if (role !== 'admin')       throw new Error('FORBIDDEN: somente administradores podem atualizar datasets');
return [{ json: prev.json, binary: prev.binary }];

// Expande rows agregados de volta em items para o Convert to File (CSV).
const rows = $('Agregar Rows1').first().json.rows || [];
return rows.map(r => ({ json: r }));

// 1) Authorization header + dataset field + arquivo binário
const item = $input.first();
const headers = item.json.headers || {};
const auth = headers.authorization || headers.Authorization;
if (!auth || !String(auth).toLowerCase().startsWith('bearer ')) {
  throw new Error('UNAUTHORIZED: missing bearer token');
}

// dataset pode vir como form field ou como query string
const body = item.json.body || {};
const query = item.json.query || {};
const dataset = String(body.dataset || query.dataset || '').trim().toLowerCase();
const valid = ['ordens_servico', 'facas', 'apontamentos'];
if (!valid.includes(dataset)) {
  throw new Error('dataset inválido. Use: ' + valid.join(', '));
}

const bin = item.binary || {};
const binKey = Object.keys(bin)[0];
if (!binKey) throw new Error('Arquivo não enviado (campo binário ausente).');
const fileMeta = bin[binKey];
const fileName = String(fileMeta.fileName || '').toLowerCase();
const mimeType = String(fileMeta.mimeType || '').toLowerCase();
let kind;
if (fileName.endsWith('.csv') || mimeType.includes('csv')) kind = 'csv';
else if (fileName.endsWith('.xlsx') || fileName.endsWith('.xls') || mimeType.includes('sheet') || mimeType.includes('excel')) kind = 'xlsx';
else throw new Error('Formato não suportado: envie .xlsx ou .csv');

return [{ json: { authHeader: auth, dataset, kind, binKey, fileName: fileMeta.fileName }, binary: bin }];

// O parser de CSV do n8n sempre le o binario como UTF-8. Planilhas do ERP saem
// em Windows-1252 ("Produ\uFFFD\uFFFDo" depois do Extract) e, as vezes, em UTF-8
// que ja foi lido como CP1252 ("Ã§Ã£o"). Aqui o binario e reescrito em UTF-8
// valido ANTES do parser, com a mesma deteccao do front (src/lib/encoding.ts).
//
// Reconstrucao de palavra ilegivel e normalizacao ASCII NAO acontecem aqui: ficam
// no no "Validar Header + Normalizar1", que vale para CSV e XLSX.

const ASSINATURA_DUPLO = /[\u00c3\u00c2][\u0080-\u00ff\u2013\u2014\u201c\u201d\u2019\u20ac]/g;
const suspeitas = (t) => (t.match(ASSINATURA_DUPLO) || []).length;

const items = $input.all();
const out = [];
for (let i = 0; i < items.length; i++) {
  const item = items[i];
  const key = item.json.binKey;
  const bin = (item.binary || {})[key];
  if (!bin) { out.push(item); continue; }

  const buf = this.helpers && this.helpers.getBinaryDataBuffer
    ? await this.helpers.getBinaryDataBuffer(i, key)
    : Buffer.from(bin.data, 'base64');

  let texto;
  let encoding;
  if (buf[0] === 0xef && buf[1] === 0xbb && buf[2] === 0xbf) {
    // BOM: se ficar no arquivo, gruda na 1a coluna e quebra o header.
    texto = buf.subarray(3).toString('utf8');
    encoding = 'utf-8 (BOM removido)';
  } else {
    try {
      // fatal: um arquivo Latin1 lanca aqui; um UTF-8 valido passa direto.
      texto = new TextDecoder('utf-8', { fatal: true }).decode(buf);
      encoding = 'utf-8';
    } catch (e) {
      texto = new TextDecoder('windows-1252').decode(buf);
      encoding = 'windows-1252';
    }
  }

  // Mojibake duplo (UTF-8 lido como CP1252): os bytes originais ainda estao la,
  // a reinterpretacao e reversivel. So aceita se reduzir as sequencias suspeitas
  // e nao introduzir caractere ilegivel.
  const antes = suspeitas(texto);
  if (antes) {
    const tentativa = Buffer.from(texto, 'latin1').toString('utf8');
    if (suspeitas(tentativa) < antes && tentativa.indexOf('\uFFFD') === -1) {
      texto = tentativa;
      encoding += ' + mojibake duplo revertido';
    }
  }

  const utf8Buf = Buffer.from(texto, 'utf8');
  const newBinary = this.helpers && this.helpers.prepareBinaryData
    ? await this.helpers.prepareBinaryData(utf8Buf, bin.fileName, bin.mimeType)
    : Object.assign({}, bin, { data: utf8Buf.toString('base64'), fileSize: utf8Buf.length + ' B' });

  console.log('[upload] encoding detectado: ' + encoding);
  out.push({
    json: Object.assign({}, item.json, { encoding_origem: encoding }),
    binary: Object.assign({}, item.binary, { [key]: newBinary }),
  });
}
return out;

// Valida cabeçalho e normaliza linhas conforme o dataset.
// O matching de cabeçalho é INSENSÍVEL a caixa, acentos e espaços/pontuação,
// portanto o usuário não precisa preservar maius/minúscula ou nome de aba.
// Em caso de cabeçalho inválido / planilha vazia, retorna um item-marcador
// { __invalid: true, __error: '...' } para o IF roteador devolver uma resposta
// amigável ao front, ANTES de qualquer carga no Drive ou no banco.

const fail = (msg) => [{ json: { __invalid: true, __error: msg } }];

const meta = $('Require Admin').first().json;
const dataset = meta.dataset;
// ---------------------------------------------------------------------------
// Limpeza de encoding, antes de qualquer mapeamento. Mesmas regras de
// .github/skills/limpeza-encoding e de front-react/src/lib/encoding.ts:
// chaves e valores chegam ao SCHEMA em ASCII puro, sem acento e sem caractere
// ilegivel. Vale para CSV e XLSX.
//
// Sem isso "Producao" e "Produ??o" viram duas categorias no GROUP BY e o join
// por nome de cliente perde linha.
// ---------------------------------------------------------------------------
const RUINA = '\uFFFD';
const ACENTUADOS = "áàâãäéèêëíìîïóòôõöúùûüçñýÁÀÂÃÄÉÈÊËÍÌÎÏÓÒÔÕÖÚÙÛÜÇÑÝºª";

// No glossario, '#' representa o caractere perdido (U+FFFD).
const GLOSSARIO = {};
for (const par of "Produ##o=Producao|Refei##o=Refeicao|Tripula##o=Tripulacao|Manuten##o=Manutencao|Confec##o=Confeccao|Prepara##o=Preparacao|Organiza##o=Organizacao|Grava##o=Gravacao|Libera##o=Liberacao|Aprova##o=Aprovacao|Solu##o=Solucao|Lo##o=Locao|Nutri##o=Nutricao|Concentra##o=Concentracao|Dire##o=Direcao|Exporta##o=Exportacao|Reprodu##o=Reproducao|Licita##o=Licitacao|Lubrifica##o=Lubrificacao|posi##es=posicoes|a##car=acucar|A##car=Acucar|Descri##o=Descricao|M#quina=Maquina|m#q=maq|Impress#o=Impressao|Suspens#o=Suspensao|Emuls#o=Emulsao|Cart#o=Cartao|Padr#o=Padrao|Reuni#o=Reuniao|Lim#o=Limao|Ber#o=Berco|ber#o=berco|Servi#o=Servico|Crian#a=Crianca|Ma#a=Maca|Clich#=Cliche|Conclu#da=Concluida|In#cio=Inicio|T#tulo=Titulo|Jo#o=Joao|Andr#=Andre|Farmac#utica=Farmaceutica|Ind#stria=Industria|Qu#mica=Quimica|Medqu#mica=Medquimica|Farmoqu#micos=Farmoquimicos|Laborat#rio=Laboratorio|Pl#sticos=Plasticos|Sa#de=Saude|Braster#pica=Brasterapica|Itajub#=Itajuba|An#polis=Anapolis|Agua#=Aguai|c#psulas=capsulas|C#psulas=Capsulas|c#ps=caps|C#ps=Caps|c#p=cap|C#p=Cap|#leo=Oleo|#mega=Omega|#cido=Acido|#ndia=India|#nica=Unica|P#=Po|p#=po|P#o=Pao|P#ssego=Pessego|P#tals=Petals|N#=N|01#=01|C#lcio=Calcio|C#lcica=Calcica|C#l=Cal|S#dio=Sodio|S#dico=Sodico|Magn#sio=Magnesio|Pot#ssico=Potassico|Col#geno=Colageno|Hem#cias=Hemacias|Hialur#nico=Hialuronico|Zoledr#nico=Zoledronico|Tranex#mico=Tranexamico|Tiocolchicos#deo=Tiocolchicosideo|Ondansetr#n=Ondansetron|Etop#sido=Etoposido|Ep#sido=Eposido|T#tano=Tetano|Antirr#bico=Antirrabico|Antidift#rico=Antidifterico|Antielap#dico=Antielapidico|Anticrot#lico=Anticrotalico|Antiaracn#dico=Antiaracnidico|Antibotr#pico=Antibotropico|Antibotul#nico=Antibotulinico|Antilaqu#lico=Antilaquetico|Polivitam#nico=Polivitaminico|Probi#tico=Probiotico|Pedi#trico=Pediatrico|Gen#rico=Generico|L#quido=Liquido|T#pica=Topica|Qu#ntuplo=Quintuplo|Divis#ria=Divisoria|V#lvula=Valvula|Piv#=Pivo|An#is=Aneis|an#is=aneis|sach#s=saches|Sach#s=Saches|Hamb#rguer=Hamburguer|Sandu#che=Sanduiche|Avel#=Avela|Guaran#=Guarana|Maracuj#=Maracuja|Pur#=Pure|Ver#o=Verao|Beb#=Bebe|H#lito=Halito|Combust#vel=Combustivel|d'#gua=d'agua|#c.=Ac.|ACH#=ACHE|Z#=Ze|Cald#=Calde|Qualit#=Qualita|Iros#=Irose|Aid#=Aide|Mi#=Mio|Phit#ss=Phitoss|Gripalc#=Gripalce|Belgl#s=Belglos|Sarn#rico=Sarnerico".split('|')) {
  const eq = par.indexOf('=');
  GLOSSARIO[par.slice(0, eq).split('#').join(RUINA)] = par.slice(eq + 1);
}
const CHAVES_GLOSSARIO = Object.keys(GLOSSARIO).sort((a, b) => b.length - a.length);

// A classe exclui os separadores de coluna: sem isso o token atravessa a celula.
const TOKEN_QUEBRADO = new RegExp('[^\\s,;|\\t"\\r\\n]*' + RUINA + '[^\\s,;|\\t"\\r\\n]*', 'g');
const PALAVRA = new RegExp('[0-9A-Za-z' + ACENTUADOS + "'.]+", 'g');

// Substituicoes que a remocao de acento (NFD) nao resolve sozinha.
const ESPECIAIS = {
  '\uFEFF': '', '\u00ba': '', '\u00b0': '', '\u00aa': '', '\u00b4': "'",
  '\u2019': "'", '\u2018': "'", '\u201c': '"', '\u201d': '"',
  '\u2013': '-', '\u2014': '-', '\u00a0': ' ', '\u00b5': 'u', '\u00d7': 'x',
  '\u00f7': '/', '\u20ac': 'EUR', '\u00a3': 'GBP', '\u00a5': 'JPY',
  '\u2026': '...', '\u2022': '-', '\u00ad': '',
};
// Trocas de letra que o NFD nao cobre (nao sao acento, sao letras proprias).
const LETRAS = {
  '\u00e7': 'c', '\u00c7': 'C', '\u00f1': 'n', '\u00d1': 'N', '\u00f0': 'd',
  '\u00d0': 'D', '\u00fe': 'th', '\u00de': 'Th', '\u00e6': 'ae', '\u00c6': 'AE',
  '\u00f8': 'o', '\u00d8': 'O', '\u00df': 'ss', '\u0142': 'l', '\u0141': 'L',
  '\u0111': 'd', '\u0110': 'D',
};

const escapeRe = (s) => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
const semAcento = (t) => Array.from(t).map(c => LETRAS[c] || c).join('')
  .normalize('NFD').replace(/[\u0300-\u036f]/g, '');
const paraAscii = (t) => Array.from(t)
  .map(c => (ESPECIAIS[c] !== undefined ? ESPECIAIS[c] : (LETRAS[c] || c))).join('')
  .normalize('NFD').replace(/[\u0300-\u036f]/g, '');

// Descobre o que era um token com U+FFFD, da fonte mais confiavel para a menos:
// glossario -> composicao de entradas do glossario -> lexico do proprio lote.
// Devolve [valor, metodo]; valor null = precisa de decisao humana.
function resolverToken(token, lexico) {
  if (GLOSSARIO[token]) return [GLOSSARIO[token], 'glossario'];

  const nucleo = token.replace(/^[.,;:()[\]{}/-]+/, '').replace(/[.,;:()[\]{}/-]+$/, '');
  if (GLOSSARIO[nucleo]) return [token.split(nucleo).join(GLOSSARIO[nucleo]), 'glossario'];

  // Token composto ("Menta-Lim?o", "Cx.V?lvula"): aplica o glossario de dentro do
  // token, da chave mais longa para a mais curta. Chave curta ("P?", "N?") so
  // vale solta, senao "P?ssego" viraria "Possego".
  let composto = token;
  for (const chave of CHAVES_GLOSSARIO) {
    if (composto.indexOf(chave) === -1) continue;
    const valor = GLOSSARIO[chave];
    if (chave.split(RUINA).join('').length < 3) {
      composto = composto.replace(new RegExp('(?<![A-Za-z])' + escapeRe(chave) + '(?![A-Za-z])', 'g'), () => valor);
    } else {
      composto = composto.split(chave).join(valor);
    }
  }
  if (composto.indexOf(RUINA) === -1) return [composto, 'glossario (composicao)'];

  // Fator 1 = um caractere perdido por marcador; fator 2 = um byte por marcador.
  for (const fator of [1, 2]) {
    let alvo = nucleo;
    if (fator === 2) {
      if (alvo.indexOf(RUINA + RUINA) === -1) continue;
      alvo = alvo.split(RUINA + RUINA).join(RUINA);
    }
    const padrao = new RegExp('^' + Array.from(alvo)
      .map(c => (c === RUINA ? '[' + ACENTUADOS + ']' : escapeRe(c))).join('') + '$');
    const formas = new Set();
    let candidatos = 0;
    for (const p of lexico) if (padrao.test(p)) { formas.add(semAcento(p)); candidatos++; }
    if (formas.size === 1) {
      return [token.split(nucleo).join(Array.from(formas)[0]), 'lexico (' + candidatos + ' candidato)'];
    }
    if (formas.size > 1) return [null, 'ambiguo: ' + Array.from(formas).sort().slice(0, 4).join(', ')];
  }
  return [null, 'sem candidato no lexico'];
}

const brutas = $input.all().map(i => i.json);
if (!brutas.length) return fail('Planilha vazia.');

// Lexico: a mesma palavra costuma aparecer intacta em outra celula do lote.
const lexico = new Set();
for (const r of brutas) {
  for (const k of Object.keys(r)) {
    for (const fonte of [k, r[k]]) {
      if (typeof fonte !== 'string') continue;
      for (const p of fonte.match(PALAVRA) || []) {
        if (Array.from(p).some(c => ACENTUADOS.indexOf(c) !== -1)) lexico.add(p);
      }
    }
  }
}

const cache = new Map();
const pendencias = new Map();
function limparTexto(valor) {
  if (typeof valor !== 'string' || !valor) return valor;
  let s = valor;
  if (s.indexOf(RUINA) !== -1) {
    // Um passe unico casando o token inteiro: trocar por substring solta faria a
    // chave "P?" atingir tambem o miolo de "P?ssego".
    s = s.replace(TOKEN_QUEBRADO, (tk) => {
      if (!cache.has(tk)) cache.set(tk, resolverToken(tk, lexico));
      const par = cache.get(tk);
      if (par[0] === null) {
        const p = pendencias.get(tk) || { token: tk, ocorrencias: 0, motivo: par[1] };
        p.ocorrencias++;
        pendencias.set(tk, p);
        return tk;
      }
      return par[0];
    });
  }
  return paraAscii(s);
}

const rows = brutas.map((r) => {
  const limpa = {};
  for (const k of Object.keys(r)) limpa[limparTexto(k)] = limparTexto(r[k]);
  return limpa;
});

// Pendencia = palavra destruida na origem que o glossario nao reconstroi. Parar
// custa uma reexportacao; gravar um chute custa uma correcao em producao depois
// que alguem ja usou o dado.
if (pendencias.size) {
  const lista = Array.from(pendencias.values())
    .sort((a, b) => b.ocorrencias - a.ocorrencias).slice(0, 10)
    .map(p => '"' + p.token + '" (' + p.ocorrencias + 'x - ' + p.motivo + ')');
  return fail('A planilha tem ' + pendencias.size + ' termo(s) ilegivel(is) que nao foi possivel reconstruir com seguranca: '
    + lista.join(', ') + '. Reexporte o arquivo em UTF-8 na origem ou registre esses termos no glossario '
    + '(.github/skills/limpeza-encoding/scripts/glossario.json e front-react/src/lib/glossarioEncoding.ts).');
}

const norm = s => String(s ?? '')
  .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
  .toLowerCase().replace(/[^a-z0-9]+/g, '');

// Constrói índice case/acento-insensitivo do row.
// Também indexa a parte APÓS o último '.' (para casar headers do ERP tipo
// 'ctporc.Tipo de serviço' contra o alias 'tipo de servico').
function buildIndex(row) {
  const idx = {};
  for (const k of Object.keys(row)) {
    const n = norm(k);
    if (n) idx[n] = row[k];
    const ks = String(k);
    const dot = ks.lastIndexOf('.');
    if (dot >= 0 && dot < ks.length - 1) {
      const tn = norm(ks.substring(dot + 1));
      if (tn && idx[tn] === undefined) idx[tn] = row[k];
    }
  }
  return idx;
}

const toInt = v => { const n = parseInt(String(v ?? '').replace(/[^\d-]/g,''), 10); return isNaN(n) ? null : n; };
const toBool = v => { const s = String(v ?? '').trim().toLowerCase(); return s === 'sim' || s === 'true' || s === '1' || s === 's'; };
const toStr = v => { const s = String(v ?? '').trim(); return s.length ? s : null; };
const pad2 = n => String(n).padStart(2,'0');
const toInterval = v => {
  // Devolve string 'HH:MM:SS' (PG cast ::interval); null se vazio/invalido.
  if (v === null || v === undefined || v === '') return null;
  // Número: Excel costuma usar fração de DIA (0.5 = 12h). Se > 1, tratamos como horas decimais.
  if (typeof v === 'number') {
    if (!isFinite(v) || v < 0) return null;
    const totalSec = v <= 1 ? Math.round(v * 86400) : Math.round(v * 3600);
    const h = Math.floor(totalSec / 3600);
    const m = Math.floor((totalSec % 3600) / 60);
    const s = totalSec % 60;
    return `${pad2(h)}:${pad2(m)}:${pad2(s)}`;
  }
  let s = String(v).trim();
  if (!s) return null;
  // Já vem como HH:MM ou HH:MM:SS
  let m = s.match(/^(\d{1,3}):(\d{1,2})(?::(\d{1,2}))?$/);
  if (m) return `${pad2(parseInt(m[1],10))}:${pad2(parseInt(m[2],10))}:${pad2(parseInt(m[3]||'0',10))}`;
  // Decimal de horas: '2.35' ou '2,35'
  const num = parseFloat(s.replace(',','.'));
  if (!isNaN(num) && num >= 0) {
    const totalSec = num <= 1 ? Math.round(num * 86400) : Math.round(num * 3600);
    const h = Math.floor(totalSec / 3600);
    const mm = Math.floor((totalSec % 3600) / 60);
    const ss = totalSec % 60;
    return `${pad2(h)}:${pad2(mm)}:${pad2(ss)}`;
  }
  return null;
};
const toTs = v => {
  if (v === null || v === undefined || v === '') return null;
  if (typeof v === 'number') { // Excel serial
    const ms = Math.round((v - 25569) * 86400 * 1000);
    return new Date(ms).toISOString();
  }
  const d = new Date(v);
  return isNaN(d.getTime()) ? null : d.toISOString();
};

// dataset -> {requiredAny: aliases por coluna lógica, map: fn(rowIdx)->dbRow}
const SCHEMA = {
  ordens_servico: {
    columns: {
      nro_os:         ['nro os', 'nro_os', 'numero os', 'n os', 'os'],
      titulo:         ['titulo', 'título', 'descricao', 'descrição'],
      nome_cliente:   ['nome cliente', 'cliente', 'nome do cliente'],
      quantidade:     ['quantidade', 'qtd', 'qtde'],
      tipo_servico:   ['tipo de servico', 'tipo serviço', 'tipo_servico', 'ctporc tipo de serviço'],
      setor:          ['setor', 'clsvc descricao', 'segmento', 'descricao do setor'],
      tipo_orcamento: ['tipo orcamento', 'tipo orçamento', 'tipo_orcamento'],
      repetido:       ['repetido', 'repete'],
      repetiu_erro:   ['repetiu erro', 'repetiu/erro', 'refugo', 'retrabalho']
    },
    required: ['nro_os', 'titulo', 'nome_cliente'],
    build: (g) => ({
      nro_os:         toStr(g('nro_os')),
      titulo:         toStr(g('titulo')),
      nome_cliente:   toStr(g('nome_cliente')),
      quantidade:     toInt(g('quantidade')),
      tipo_servico:   toStr(g('tipo_servico')),
      setor:          toStr(g('setor')),
      tipo_orcamento: toStr(g('tipo_orcamento')),
      repetido:       toStr(g('repetido')),
      repetiu_erro:   toBool(g('repetiu_erro'))
    })
  },
  facas: {
    columns: {
      nro_os:       ['nro os', 'nro_os', 'os'],
      faca:         ['faca', 'codigo faca', 'cod faca'],
      lado_1:       ['lado 1', 'lado_1', 'l1', 'lado1'],
      lado_2:       ['lado 2', 'lado_2', 'l2', 'lado2'],
      montagem:     ['montagem'],
      l1_substrato: ['l1 substrato', 'lado 1 substrato', 'substrato 1'],
      l2_substrato: ['l2 substrato', 'lado 2 substrato', 'substrato 2'],
      l1_corte:     ['l1 corte', 'lado 1 corte', 'corte 1'],
      l2_corte:     ['l2 corte', 'lado 2 corte', 'corte 2']
    },
    required: ['nro_os', 'faca'],
    build: (g) => ({
      nro_os:       toStr(g('nro_os')),
      faca:         toStr(g('faca')),
      lado_1:       toStr(g('lado_1')),
      lado_2:       toStr(g('lado_2')),
      montagem:     toStr(g('montagem')),
      l1_substrato: toStr(g('l1_substrato')),
      l2_substrato: toStr(g('l2_substrato')),
      l1_corte:     toStr(g('l1_corte')),
      l2_corte:     toStr(g('l2_corte'))
    })
  },
  apontamentos: {
    columns: {
      equipamento:  ['codeq nome do equipamento', 'codeq.nome do equipamento', 'nome do equipamento', 'equipamento', 'maquina', 'máquina'],
      inicio:       ['inicio', 'início', 'data inicio', 'data início', 'inicio do apontamento'],
      fim:          ['fim', 'data fim', 'fim do apontamento'],
      tipo_apontam: ['tipo apontam', 'tipo apontam.', 'tipo de apontamento', 'tipo apontamento', 'tipo'],
      tempo_total:  ['tempo total', 'duracao', 'duração'],
