const schema = SCHEMA[dataset];
if (!schema) return fail('Dataset não reconhecido: ' + dataset);

// Resolve, a partir da UNIÃO das chaves de todas as linhas, qual chave fisica do header bate em cada coluna logica.
// Importante: XLSX/CSV podem omitir chaves quando a célula está vazia, então não podemos olhar só rows[0].
// A prioridade respeita a ORDEM dos aliases declarados no SCHEMA: o primeiro alias
// declarado que existir no arquivo vence. Isso evita que uma coluna genérica vazia
// (ex: 'Nro OS') roube a vez de uma coluna específica com dados (ex: 'numos.Nro OS').
// Também expõe variantes 'pós-ponto' para tolerar headers do tipo 'ctporc.Tipo de serviço'.
const availableKeys = new Set();
for (const r of rows) for (const k of Object.keys(r)) {
  const n = norm(k);
  if (n) availableKeys.add(n);
  const ks = String(k);
  const dot = ks.lastIndexOf('.');
  if (dot >= 0 && dot < ks.length - 1) {
    const tn = norm(ks.substring(dot + 1));
    if (tn) availableKeys.add(tn);
  }
}
const availableKeysArr = Array.from(availableKeys);
const headerMap = {};
for (const [logical, aliases] of Object.entries(schema.columns)) {
  for (const alias of aliases) {
    const n = norm(alias);
    if (availableKeys.has(n)) { headerMap[logical] = n; break; }
  }
}
console.log('[upload] dataset=' + dataset + ' detected_headers=' + JSON.stringify(availableKeysArr));
console.log('[upload] header_map=' + JSON.stringify(headerMap));

const missingRequired = schema.required.filter(c => !headerMap[c]);
if (missingRequired.length) {
  const detected = availableKeysArr.length ? availableKeysArr.join(', ') : '(nenhuma)';
  const expected = Object.keys(schema.columns).join(', ');
  return fail("Cabeçalho do arquivo não corresponde ao esperado para a tabela '" + dataset + "'. Colunas obrigatórias ausentes: " + missingRequired.join(', ') + '. Colunas esperadas: ' + expected + '. Colunas detectadas no arquivo: ' + detected + '.');
}

// Defesa adicional: ao menos METADE das colunas declaradas no schema precisam casar.
// Isso impede que uma planilha completamente diferente, mas que por acaso tenha um
// 'Nro OS', seja aceita para o dataset errado.
const totalCols = Object.keys(schema.columns).length;
const mappedCols = Object.keys(headerMap).length;
if (mappedCols * 2 < totalCols) {
  const expected = Object.keys(schema.columns).join(', ');
  const mapped = Object.keys(headerMap).join(', ') || '(nenhuma)';
  return fail("O arquivo enviado não parece ser da tabela '" + dataset + "'. Apenas " + mappedCols + ' de ' + totalCols + ' colunas esperadas foram reconhecidas (' + mapped + '). Colunas esperadas: ' + expected + '.');
}

const getter = (idx) => (logical) => {
  const phys = headerMap[logical];
  return phys === undefined ? null : idx[phys];
};

const out = [];
for (const r of rows) {
  const idx = buildIndex(r);
  const built = schema.build(getter(idx));
  // ignora linhas vazias
  const hasAnyValue = Object.values(built).some(v => v !== null && v !== '' && v !== undefined);
  if (hasAnyValue) out.push(built);
}
if (!out.length) return fail('Nenhuma linha válida encontrada na planilha.');

return out.map(json => ({ json }));

